                <span class="description">{event.description}</span>
                <span class="source">{event.source}</span>
                <div class="location">{event.location}</div>
                <span class="date"
                    >{event.date.toLocaleString(page.data.lang)}</span
                >
            </div>
        {/each}
    </div>
{/if}

{#if form?.failedClients.length ?? 0 > 0}
    <p class="failed">
        {i18n("unavailable_sources")}: {form!.failedClients.join(", ")}
    </p>
{/if}

<form class="lang-select">
    <label for="lang">{i18n("language")}: </label>
    <select name="lang">
        <option value="en" selected={page.data.lang === "en"}>English</option>
        <option value="ru" selected={page.data.lang === "ru"}>Русский</option>
    </select>
    <input type="submit" value={i18n("apply")} />
</form>

