    :global(*) {
        font-family: "Inter", system-ui, sans-serif, serif, "Arial", "Helvetica";
    }

    :global(body) {
        margin: 16px;
        font-size: 16px;
    }

    input[type="submit"] {
        height: 42px;
        border: none;
        cursor: pointer;
        padding: 0px 12px 0px 12px;
        border-radius: 24px;
        font-weight: 600;
    }

    select {
        height: 42px;
        border: none;
        padding: 0px 12px 0px 12px;
        cursor: pointer;
        border-radius: 24px;
        font-weight: 600;
    }

    input[type="text"] {
        background-color: transparent;
        height: 42px;
        padding: 0px 12px 0px 12px;
        border: 1px solid #a5a5ac;
        border-radius: 24px;
    }

    input[type="text"]:focus {
        border: 1px solid #000000;
    }

    .source,
    .location {
        color: #8f7e77;
    }

    .location,
    input[name="track_number"] {
        font-family: "JetBrains Mono";
    }

    .source,
    .location {
        font-size: 12px;
    }

    .description,
    .location {
        font-weight: 600;
    }

    .row {
        max-width: 600px;
        padding: 12px 16px 12px 16px;
        border: 1px solid #a5a5ac;
