    }

    .row:first-child {
        border-top: 1px solid #a5a5ac;
        border-radius: 12px 12px 0px 0px;
    }

    .row:last-child {
        border-radius: 0px 0px 12px 12px;
    }

    .lang-select {
        margin-top: 16px;
    }

    .inputs {
        margin: 16px 0px 16px 0px;
    }
</style>
